def update_hotel_quote(property_id, room_type, requested_rooms, fetch_rooms, refresh_quote, now):
    if fetch_rooms(property_id, room_type) < requested_rooms:
        return None
    quote = refresh_quote(property_id, room_type, requested_rooms)
    if quote is None or now >= quote['expires_at']:
        return None
    return quote

