def revalidate_flight(itinerary_id, check_status, refresh_quote, now):
    status = check_status(itinerary_id)
    quote = refresh_quote(itinerary_id)
    if status != 'available' or quote is None:
        return False, None
    if now >= quote['expires_at']:
        return False, None
    return True, quote

